div.style:
height: 350px;
padding: 10px;
background-color: white;
border-radius: 10px;
box-shadow: 0 0 5px rgba(0,0,0,0.1);

height: 350px;
padding: 10px;
background-color: white;
border-radius: 10px;
box-shadow: 0 0 5px rgba(0,0,0,0.1);

height: 100px;
padding: 10px;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
background-color: white;
border-radius: 10px;
box-shadow: 0 0 5px rgba(0,0,0,0.31);

height: 100px;
padding: 10px;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
background-color: white;
border-radius: 10px;
box-shadow: 0 0 5px rgba(0,0,0,0.31);

div.script:
document.addEventListener("DOMContentLoaded", function () {
document.querySelectorAll(".property-cards").forEach(function (card) {
	card.addEventListener("click", function (e) {
	// Prevent click if it originated from the button
	if (e.target.closest("button")) return;

	const form = card.closest("form");
	if (form) {
		form.submit();
	}
	});
});
});
